struct ConductorServiceSettings: Sendable {
    let conductorEndpoint: URL
    let serviceName: String
    let serviceURL: URL
    let logDirectoryURL: URL

    var bindHost: String? {
        guard let host = serviceURL.host?.lowercased() else {
            return nil
        }
        if host == "127.0.0.1" || host == "localhost" {
            return "0.0.0.0"
        }
        return host
    }

    var bindPort: Int? {
        if let port = serviceURL.port {
            return port
        }
        switch serviceURL.scheme?.lowercased() {
        case "https":
            return 443
        case "http":
            return 80
        default:
            return nil
        }
    }
}

struct AppLaunchContext {
    let conductorSettings: ConductorServiceSettings?
    let conductorStartupMessage: String?

    init(arguments: [String]) {
        guard let conductorEndpoint = ConductorIntegration.endpointArgument(from: arguments) else {
            conductorSettings = nil
            conductorStartupMessage = nil
            return
        }

        do {
            let settings = try ConductorIntegration.fetchStartupSettings(conductorEndpoint: conductorEndpoint)
            conductorSettings = settings
            conductorStartupMessage = "conductor startup override active: endpoint=\(settings.serviceURL.absoluteString) log_dir=\(settings.logDirectoryURL.path)"
        } catch {
            conductorSettings = nil
            conductorStartupMessage = "conductor startup override failed: \(error.localizedDescription)"
        }
    }
}

enum ConductorIntegration {
    static let serviceName = "dictator"

    static func endpointArgument(from arguments: [String]) -> URL? {
        guard arguments.count == 2 else {
            return nil
        }
        return normalizedURL(arguments[1])
    }

    static func fetchStartupSettings(conductorEndpoint: URL, session: URLSession = .shared) throws -> ConductorServiceSettings {
        let servicesURL = try endpointURL(base: conductorEndpoint, path: "/services", queryItems: [
            URLQueryItem(name: "name", value: serviceName)
        ])
        var request = URLRequest(url: servicesURL)
        request.httpMethod = "GET"

        let (data, response) = try sendSync(request, session: session)
        guard let http = response as? HTTPURLResponse else {
            throw ConductorIntegrationError.invalidResponse("missing HTTP response")
        }
        guard (200..<300).contains(http.statusCode) else {
            throw ConductorIntegrationError.requestFailed("services lookup failed with HTTP \(http.statusCode)")
        }

        let decoded = try JSONDecoder().decode(ServicesResponse.self, from: data)
        guard let service = decoded.services.first else {
            throw ConductorIntegrationError.requestFailed("service '\(serviceName)' is not registered in conductor")
        }
        guard let serviceURL = normalizedURL(service.url) else {
            throw ConductorIntegrationError.invalidResponse("registered service URL is invalid: \(service.url)")
        }

        return ConductorServiceSettings(
            conductorEndpoint: normalizedBaseURL(conductorEndpoint),
            serviceName: service.name,
            serviceURL: serviceURL,
            logDirectoryURL: URL(fileURLWithPath: service.logDir, isDirectory: true)
        )
    }

    static func requestServiceRestart(conductorEndpoint: URL, serviceName: String = serviceName, session: URLSession = .shared) async throws {
        let restartURL = try endpointURL(base: conductorEndpoint, path: "/restart_service")
        var request = URLRequest(url: restartURL)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = try JSONEncoder().encode(RestartRequest(name: serviceName))

        let (_, response) = try await session.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw ConductorIntegrationError.invalidResponse("missing HTTP response")
        }
        guard (200..<300).contains(http.statusCode) else {
            throw ConductorIntegrationError.requestFailed("restart failed with HTTP \(http.statusCode)")
        }
    }

    private static func sendSync(_ request: URLRequest, session: URLSession) throws -> (Data, URLResponse) {
        let semaphore = DispatchSemaphore(value: 0)
        let lock = NSLock()
        var result: Result<(Data, URLResponse), Error>?

        let task = session.dataTask(with: request) { data, response, error in
            lock.lock()
            defer {
                lock.unlock()
                semaphore.signal()
            }

            if let error {
                result = .failure(error)
                return
            }
            guard let data, let response else {
                result = .failure(ConductorIntegrationError.invalidResponse("missing response payload"))
                return
            }
            result = .success((data, response))
        }
        task.resume()
        semaphore.wait()

        guard let result else {
            throw ConductorIntegrationError.invalidResponse("request completed without a result")
        }
        return try result.get()
    }

    private static func endpointURL(base: URL, path: String, queryItems: [URLQueryItem] = []) throws -> URL {
        guard var components = URLComponents(url: normalizedBaseURL(base), resolvingAgainstBaseURL: false) else {
            throw ConductorIntegrationError.invalidResponse("invalid conductor endpoint: \(base.absoluteString)")
        }
        components.path = path
        components.queryItems = queryItems.isEmpty ? nil : queryItems
        guard let url = components.url else {
            throw ConductorIntegrationError.invalidResponse("could not construct conductor URL for path \(path)")
        }
        return url
    }

    private static func normalizedBaseURL(_ url: URL) -> URL {
        guard var components = URLComponents(url: url, resolvingAgainstBaseURL: false) else {
            return url
        }
        if components.path.isEmpty {
            components.path = ""
        }
        if components.path.count > 1, components.path.hasSuffix("/") {
            components.path.removeLast()
        }
        components.query = nil
        components.fragment = nil
        return components.url ?? url
    }

    private static func normalizedURL(_ raw: String) -> URL? {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, var components = URLComponents(string: trimmed), components.scheme != nil, components.host != nil else {
            return nil
        }
        if components.path.count > 1, components.path.hasSuffix("/") {
            components.path.removeLast()
        }
        return components.url
    }

    private struct ServicesResponse: Decodable {
        let services: [RegisteredService]
    }

    private struct RegisteredService: Decodable {
        let name: String
        let url: String
        let logDir: String

        enum CodingKeys: String, CodingKey {
            case name
            case url
            case logDir = "log_dir"
        }
    }

    private struct RestartRequest: Encodable {
        let name: String
    }
}

enum ConductorIntegrationError: LocalizedError {
    case invalidResponse(String)
    case requestFailed(String)

    var errorDescription: String? {
        switch self {
        case let .invalidResponse(message), let .requestFailed(message):
            return message
        }
    }
}

