    static let dictationInProgressKey = "dictation_in_progress"
    static let hostSessionActiveKey = "host_session_active"
    static let hostSessionHeartbeatAtKey = "host_session_heartbeat_at"
    static let conductorTraceName = "dictator-ios"
    private static let conductorTraceLookupServiceName = "dictator"
    private static let conductorPort = 9000
    private static let conductorTraceDirectoryKey = "ios_conductor_trace_dir"
    private static let conductorTraceBaseURLKey = "ios_conductor_trace_base_url"
    private static let diagnosticsLock = NSLock()
    private static let keyboardSessionEncoder: JSONEncoder = {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .millisecondsSince1970
        return encoder
    }()
    private static let keyboardSessionDecoder: JSONDecoder = {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .millisecondsSince1970
        return decoder
    }()
    private static let traceFormatter: ISO8601DateFormatter = {
