        #expect(SharedConfig.conductorTraceURL(serverURLString: "http://dictator.local:8787")?.absoluteString == "http://dictator.local:9000/trace")
        #expect(SharedConfig.conductorTraceURL(serverURLString: "https://dictator.local:8787")?.absoluteString == "https://dictator.local:9000/trace")
        #expect(SharedConfig.conductorTraceURL(serverURLString: "http://dictator.local")?.absoluteString == "http://dictator.local:9000/trace")
    }

    @Test func invalidConfiguredServerURLSkipsTracePosting() async throws {
        let harness = try DiagnosticsHarness(serverURLString: "not a url")
        defer { harness.reset() }

        let line = SharedConfig.appendDiagnosticsEvent("hello from tests", source: "host-app", now: harness.fixedDate)
        #expect(line.contains("hello from tests"))

        try await harness.waitForIdleNetworkWindow()

        let persisted = try harness.readLog()
        #expect(persisted.contains("hello from tests"))
        #expect(harness.requests.isEmpty)
    }

    @Test func diagnosticsLoggingAppendsLocallyAndPostsToConductor() async throws {
        let harness = try DiagnosticsHarness(serverURLString: "http://dictator.local:8787")
        defer { harness.reset() }

        let line = SharedConfig.appendDiagnosticsEvent(
            "[ABCDEF12] upload completed",
            source: "host-app",
            sessionID: "session-123",
            requestID: "ABCDEF12",
            now: harness.fixedDate
        )
        #expect(line.contains("upload completed"))

        let requests = try await harness.waitForRequests(count: 2)
        let persisted = try harness.readLog()
        #expect(persisted.contains("upload completed"))
        #expect(!persisted.contains("conductor post failed"))

        let getRequest = try #require(requests.first(where: { $0.httpMethod == "GET" }))
        #expect(getRequest.url?.absoluteString == "http://dictator.local:9000/services?name=dictator")

        let postRequest = try #require(requests.first(where: { $0.httpMethod == "POST" }))
        let body = try #require(postRequest.httpBody)
        let jsonObject = try JSONSerialization.jsonObject(with: body) as? [String: Any]
        let json = try #require(jsonObject)
        #expect(json["name"] as? String == SharedConfig.conductorTraceName)
        #expect(json["trace_dir"] as? String == "/tmp/conductor-traces")

        let payload = try #require(json["payload"] as? [String: Any])
        #expect(payload["message"] as? String == "[ABCDEF12] upload completed")
        #expect(payload["rendered_message"] as? String == line)
        #expect(payload["source"] as? String == "host-app")
        #expect(payload["session_id"] as? String == "session-123")
        #expect(payload["request_id"] as? String == "ABCDEF12")
        #expect((payload["occurred_at"] as? String)?.isEmpty == false)
    }

    @Test func conductorFailuresStayLocalAndDoNotLoop() async throws {
        let harness = try DiagnosticsHarness(
            serverURLString: "http://dictator.local:8787",
            serviceLookupStatus: 500,
            serviceLookupBody: #"{"error":"boom"}"#
        )
        defer { harness.reset() }

        SharedConfig.appendDiagnosticsEvent("network unhappy", source: "keyboard-extension", now: harness.fixedDate)

        _ = try await harness.waitForRequests(count: 1)
        try await harness.waitForLogSubstring("conductor post failed")

        let persisted = try harness.readLog()
